/**
 * Helpers for treating a donation/payment link as a UPI destination.
 *
 * Organisers frequently put a UPI address (VPA) such as `alumni@okhdfcbank` — or a ready-made
 * `upi://pay?...` deep link — where a donation URL is expected. Rendering those as ordinary links
 * makes them either inert or, worse, `mailto:` links. Converting them to a `upi://pay` URI lets the
 * device hand the tap off to an installed UPI app.
 */

const UPI_SCHEME = 'upi:';

// VPA handles are a single label without a dot (`ybl`, `okaxis`, `paytm`, …). Requiring the absence
// of a dot is what keeps ordinary email addresses (`someone@gmail.com`) out of the UPI path.
const VPA_PATTERN = /^[a-z0-9][a-z0-9._-]{1,255}@[a-z][a-z0-9]{1,63}$/i;

// The NPCI-issued handles are the exception: they are dotted, so they are matched explicitly.
const DOTTED_UPI_HANDLE_PATTERN = /^[a-z0-9][a-z0-9._-]{1,255}@(?:[a-z0-9-]+\.)*(?:ifsc\.npci|npci|upi)$/i;

// Account references such as `123456789@BKID0001234` are bank/transaction identifiers, not VPAs;
// the handle there is an IFSC code (4 letters, a `0`, then 6 alphanumerics).
const IFSC_HANDLE_PATTERN = /^[a-z]{4}0[a-z0-9]{6}$/i;

const stripMailto = (value: string): string =>
    value.replace(/^mailto:/i, '');

/** True when the value is a `upi://` deep link. */
export const isUpiUri = (value: string | null | undefined): boolean =>
    typeof value === 'string' && value.trim().toLowerCase().startsWith(`${UPI_SCHEME}//`);

/** True when the value is a UPI virtual payment address (optionally prefixed with `mailto:`). */
export const isUpiVirtualPaymentAddress = (value: string | null | undefined): boolean => {
    if (typeof value !== 'string') return false;
    const candidate = stripMailto(value.trim());
    if (!candidate || candidate.includes(' ')) return false;
    if (DOTTED_UPI_HANDLE_PATTERN.test(candidate)) return true;
    const handle = candidate.slice(candidate.lastIndexOf('@') + 1);
    if (IFSC_HANDLE_PATTERN.test(handle)) return false;
    return VPA_PATTERN.test(candidate);
};

/** True when the value can be handed to a UPI app, either as a deep link or as a VPA. */
export const isUpiPaymentTarget = (value: string | null | undefined): boolean =>
    isUpiUri(value) || isUpiVirtualPaymentAddress(value);

/** Returns the bare VPA for a UPI address, or `null` when the value is not one. */
export const getUpiVirtualPaymentAddress = (value: string | null | undefined): string | null =>
    isUpiVirtualPaymentAddress(value) ? stripMailto((value as string).trim()) : null;

interface UpiPaymentOptions {
    /** Payee name (`pn`). Some UPI apps refuse to open a deep link without it. */
    payeeName?: string | null;
    /** Transaction note (`tn`), shown to the payer inside the UPI app. */
    note?: string | null;
    /** Amount (`am`) in rupees. Omitted when absent so the payer can choose what to give. */
    amount?: string | number | null;
    /** Transaction reference (`tr`). Generated when omitted; BHIM-family apps reject links without it. */
    transactionRef?: string | null;
}

// The NPCI spec allows a 50-character note, but the stricter apps reject punctuation, so the note is
// reduced to alphanumerics and single spaces.
const sanitiseText = (value: string, maxLength: number): string =>
    value.replace(/[^a-z0-9 ]/gi, ' ').replace(/\s+/g, ' ').trim().slice(0, maxLength);

// `tr` must be unique enough that an app does not treat a retry as a duplicate of an earlier attempt.
const generateTransactionRef = (): string =>
    `AL${Date.now().toString(36)}${Math.floor(Math.random() * 1e6).toString(36)}`.toUpperCase().slice(0, 35);

/**
 * Builds a `upi://pay` URI for the given address. Existing `upi://` links are returned untouched so
 * organiser-supplied parameters (amount, merchant code, …) survive. Returns `null` when the value is
 * not a UPI target.
 */
export const buildUpiPaymentUri = (
    value: string | null | undefined,
    { payeeName, note, amount, transactionRef }: UpiPaymentOptions = {},
): string | null => {
    if (isUpiUri(value)) return (value as string).trim();

    const vpa = getUpiVirtualPaymentAddress(value);
    if (!vpa) return null;

    const params = new URLSearchParams();
    params.set('pa', vpa);
    // UPI apps show the payee name prominently; fall back to the VPA's local part when the caller
    // has nothing better, since an empty `pn` is rejected by some apps.
    params.set('pn', sanitiseText(payeeName?.trim() || vpa.split('@')[0], 50) || 'Payee');

    const cleanNote = note ? sanitiseText(note, 50) : '';
    if (cleanNote) params.set('tn', cleanNote);

    const cleanAmount = typeof amount === 'number' ? amount.toFixed(2) : amount?.trim();
    if (cleanAmount && /^\d+(\.\d{1,2})?$/.test(cleanAmount)) params.set('am', cleanAmount);

    params.set('cu', 'INR');
    // `tr` and `mode` are what the reference NPCI implementations always send, and the stricter
    // third-party apps expect them. BHIM refuses browser-originated links whatever they contain —
    // it wants a signed merchant intent — so those users are pointed at the copyable UPI ID instead.
    params.set('tr', transactionRef?.trim() ? sanitiseText(transactionRef, 35) : generateTransactionRef());
    params.set('mode', '00');

    // URLSearchParams encodes spaces as `+`; UPI apps expect percent-encoding. The `@` in the VPA is
    // left literal because that is the form UPI apps are universally tested against.
    return `upi://pay?${params.toString().replace(/\+/g, '%20').replace(/%40/g, '@')}`;
};
